"""Source-bound route geometry for LVMC 11.30.050; no legal verdicts."""
from __future__ import annotations

import math


def point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("a point needs two coordinates")
    x, y = map(float, value)
    if not all(map(math.isfinite, (x, y))):
        raise ValueError("nonfinite coordinate")
    return x, y


def segment(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("a curb segment needs two endpoints")
    a, b = map(point, value)
    if math.dist(a, b) <= 0:
        raise ValueError("zero-length curb")
    return a, b


def nearest_on_segment(start, curb):
    """Closest point on the supplied finite opposite curb, including endpoints."""
    p = point(start)
    a, b = segment(curb)
    vx, vy = b[0]-a[0], b[1]-a[1]
    u = max(0.0, min(1.0, ((p[0]-a[0])*vx+(p[1]-a[1])*vy)/(vx*vx+vy*vy)))
    return [a[0]+u*vx, a[1]+u*vy], u


def route_measurement(route, starting_curb, opposite_curb):
    """Measure original route against sourced curbs; preserve uncertainty."""
    if len(route) < 2:
        raise ValueError("crossing needs start and exit")
    path = [point(p) for p in route]
    a, b = segment(starting_curb)
    segment(opposite_curb)
    tx, ty = b[0]-a[0], b[1]-a[1]
    dx, dy = path[-1][0]-path[0][0], path[-1][1]-path[0][1]
    chord = math.hypot(dx, dy)
    if chord == 0:
        raise ValueError("zero-displacement crossing")
    polyline = sum(math.dist(u, v) for u, v in zip(path, path[1:]))
    shortest_point, fraction = nearest_on_segment(path[0], opposite_curb)
    minimum = math.dist(path[0], shortest_point)
    # Magnitude avoids choosing a curb normal or crossing direction.
    cosine_to_curb = abs((dx*tx+dy*ty)/(chord*math.hypot(tx, ty)))
    cosine_to_curb = min(1.0, max(0.0, cosine_to_curb))
    return {
        "route_points_xy_m": [list(p) for p in path],
        "entry_xy_m": list(path[0]), "exit_xy_m": list(path[-1]),
        "route_length_m": polyline, "entry_exit_chord_m": chord,
        "angle_to_starting_curb_deg": math.degrees(math.acos(cosine_to_curb)),
        "shortest_opposite_curb_point_xy_m": shortest_point,
        "shortest_opposite_curb_fraction": fraction,
        "shortest_geometric_distance_m": minimum,
        "route_excess_over_geometric_minimum_m": polyline-minimum,
        "legal_route_classification": "unresolved",
    }


def _point_in_polygon(p, polygon):
    x, y = p
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        ax, ay = a
        bx, by = b
        cross = (x-ax)*(by-ay)-(y-ay)*(bx-ax)
        if abs(cross) <= 1e-9 and min(ax, bx)-1e-9 <= x <= max(ax, bx)+1e-9 and min(ay, by)-1e-9 <= y <= max(ay, by)+1e-9:
            return True
        if (ay > y) != (by > y):
            at_x = ax + (y-ay)*(bx-ax)/(by-ay)
            if x < at_x:
                inside = not inside
    return inside


def _segments_intersect(a, b, c, d):
    def orient(p, q, r):
        return (q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0])
    ab_c = orient(a, b, c)
    ab_d = orient(a, b, d)
    cd_a = orient(c, d, a)
    cd_b = orient(c, d, b)
    if not (max(min(a[0], b[0]), min(c[0], d[0])) <= min(max(a[0], b[0]), max(c[0], d[0])) and
            max(min(a[1], b[1]), min(c[1], d[1])) <= min(max(a[1], b[1]), max(c[1], d[1]))):
        return False
    return ab_c*ab_d <= 0 and cd_a*cd_b <= 0


def crosswalk_overlap(route, polygons):
    path = [point(p) for p in route]
    for polygon in polygons:
        poly = [point(p) for p in polygon]
        if any(_point_in_polygon(p, poly) for p in path):
            return True
        for a, b in zip(path, path[1:]):
            if any(_segments_intersect(a, b, c, d) for c, d in zip(poly, poly[1:] + poly[:1])):
                return True
    return False


def validate_scene(scene):
    if scene.get("actor") != "pedestrian":
        raise ValueError("exact pedestrian actor required")
    for key in ("starting_curb_xy_m", "opposite_curb_xy_m"):
        segment(scene[key])
    measured = route_measurement(scene["route_xy_m"], scene["starting_curb_xy_m"], scene["opposite_curb_xy_m"])
    bounds = scene.get("crosswalk_boundaries_xy_m")
    if not isinstance(bounds, list) or not bounds:
        raise ValueError("marked and unmarked crosswalk inventory required")
    for polygon in bounds:
        if len(polygon) < 3:
            raise ValueError("crosswalk polygon needs at least three vertices")
        [point(vertex) for vertex in polygon]
    if scene.get("crosswalk_context") not in ("inside", "outside"):
        raise ValueError("crosswalk context required")
    inside = crosswalk_overlap(scene["route_xy_m"], bounds)
    if inside != (scene["crosswalk_context"] == "inside"):
        raise ValueError("authored route and crosswalk geometry disagree")
    if not scene.get("jurisdiction_source") or not scene.get("curb_source"):
        raise ValueError("jurisdiction and curb provenance required")
    if scene.get("control_context") is None:
        raise ValueError("governing control context required")
    return measured


def measure_original_history(rows, scene):
    """Reject missing original frame joins; requested waypoints cannot stand in for motion."""
    validate_scene(scene)
    if not rows:
        raise ValueError("original walker body history missing")
    frames = [row.get("frame") for row in rows]
    if any(type(frame) is not int for frame in frames) or len(set(frames)) != len(frames) or frames != sorted(frames):
        raise ValueError("original walker frames invalid")
    if any(row.get("source") != "original_native" for row in rows):
        raise ValueError("original Native walker source required")
    if any(row.get("actor_id") != rows[0].get("actor_id") for row in rows):
        raise ValueError("walker identity changed")
    route = [point(row["body_center_xy_m"]) for row in rows]
    if len(route) < 2:
        raise ValueError("complete crossing history required")
    if crosswalk_overlap(route, scene["crosswalk_boundaries_xy_m"]) != (scene["crosswalk_context"] == "inside"):
        raise ValueError("original route and crosswalk context disagree")
    out = route_measurement(route, scene["starting_curb_xy_m"], scene["opposite_curb_xy_m"])
    out.update({"first_frame": frames[0], "last_frame": frames[-1],
                "original_frame_count": len(frames), "actor_id": rows[0]["actor_id"],
                "crosswalk_context": scene["crosswalk_context"],
                "source_kind": "original_native"})
    return out

"""Integrity gate for independently reviewed Native crossing-site sources.

This checks source identity and exact scene bindings. It does not decide whether
the reviewed facts are true, the crossing is physically realized, or the law
applies. Those decisions require local review of the original records.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


FACTS = ('starting_curb_xy_m', 'opposite_curb_xy_m',
         'crosswalk_boundaries_xy_m', 'roadway_highway_public_use',
         'municipal_jurisdiction', 'governing_control')


def _inside(root: Path, relative: str) -> Path:
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
        raise ValueError('reviewed source path must be relative')
    path = (root / relative).resolve()
    if not path.is_relative_to(root.resolve()) or not path.is_file():
        raise ValueError('reviewed source missing or outside attempt')
    return path


def audit_reviewed_site(scene: dict, attempt: Path) -> dict:
    """Require separately reviewed original records for every physical fact."""
    attempt = Path(attempt).resolve()
    packet_path = _inside(attempt, 'reviewed-site.json')
    packet = json.loads(packet_path.read_text(encoding='utf-8'))
    if packet.get('provenance_kind') != 'reviewed_original_site':
        raise ValueError('reviewed original site provenance required')
    if packet.get('diagnostic_fixture') is not False:
        raise ValueError('diagnostic fixture cannot establish site context')
    if packet.get('case_id') != scene['case_id']:
        raise ValueError('reviewed site case mismatch')
    if packet.get('loaded_map_sha256') != scene['map_source_sha256']:
        raise ValueError('reviewed site map mismatch')
    if packet.get('starting_curb_xy_m') != scene['starting_curb_xy_m']:
        raise ValueError('reviewed starting curb differs from scene')
    if packet.get('opposite_curb_xy_m') != scene['opposite_curb_xy_m']:
        raise ValueError('reviewed opposite curb differs from scene')
    if packet.get('crosswalk_boundaries_xy_m') != scene['crosswalk_boundaries_xy_m']:
        raise ValueError('reviewed crosswalk boundaries differ from scene')
    if packet.get('roadway_highway_public_use') not in ('reviewed_public_roadway',
                                                       'reviewed_private_roadway'):
        raise ValueError('reviewed roadway/public-use finding missing')
    if packet.get('municipal_jurisdiction') not in ('reviewed_within_municipality',
                                                    'reviewed_outside_municipality'):
        raise ValueError('reviewed municipal jurisdiction finding missing')
    if packet.get('governing_control') not in ('reviewed_none', 'reviewed_device'):
        raise ValueError('reviewed governing control finding missing')
    refs = packet.get('source_refs')
    if not isinstance(refs, dict) or set(refs) != set(FACTS):
        raise ValueError('every site fact needs an exact original source')
    checked = {}
    for fact in FACTS:
        ref = refs[fact]
        if not isinstance(ref, dict) or not isinstance(ref.get('path'), str):
            raise ValueError(f'{fact} source reference malformed')
        path = _inside(attempt, ref['path'])
        if not ref['path'].startswith('reviewed-source-documents/'):
            raise ValueError(f'{fact} original source outside reviewed documents')
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        if digest != ref.get('sha256') or not path.stat().st_size:
            raise ValueError(f'{fact} original source hash/contents invalid')
        if not isinstance(ref.get('finding'), str) or not ref['finding'].strip():
            raise ValueError(f'{fact} independent finding missing')
        checked[fact] = {'path': ref['path'], 'sha256': digest}
    return {'case_id': scene['case_id'],
            'reviewed_packet_sha256': hashlib.sha256(packet_path.read_bytes()).hexdigest(),
            'source_refs': checked, 'physical_acceptance_claimed': False,
            'legal_route_classification': 'unresolved'}

"""Original pedestrian body and four-camera capture primitives.

FourViewJoin and FourVideoRecorder follow the tested C143766 worker design;
placements and walker measurements are exact to C227749 crossing geometry.
"""
from __future__ import annotations
import math
import queue
import subprocess
from pathlib import Path
from crossing_geometry import validate_scene

CAMERA_SPECS={"overview":(1920,1080),"approach":(1280,720),
              "reference_corner":(1280,720),"driver_reference":(1280,720)}

def camera_placements(scene):
    validate_scene(scene)
    route=scene["route_xy_m"]
    start=route[0];end=route[-1]
    target=((start[0]+end[0])/2,(start[1]+end[1])/2,1.0)
    sites={"overview":(target[0],target[1]+14,24),
           "approach":(start[0]-5,start[1]-5,4),
           "reference_corner":(end[0]+4,end[1]+4,5),
           "driver_reference":(start[0]-4,start[1]+4,5)}
    result={}
    for name,location in sites.items():
        dx,dy,dz=(target[i]-location[i] for i in range(3))
        yaw=math.degrees(math.atan2(dy,dx))
        pitch=math.degrees(math.atan2(dz,math.hypot(dx,dy)))
        result[name]={"location_xyz_m":location,"rotation_pitch_yaw_deg":(pitch,yaw),
                      "target_xyz_m":target}
    return result

def spawn_native_cameras(world,scene,carla):
    placements=camera_placements(scene)
    sensors={}
    try:
        for name,(width,height) in CAMERA_SPECS.items():
            blueprint=world.get_blueprint_library().find("sensor.camera.rgb")
            if blueprint is None:raise ValueError("Native RGB camera blueprint missing")
            for key,value in (("image_size_x",width),("image_size_y",height),("fov",75)):
                blueprint.set_attribute(key,str(value))
            placement=placements[name]
            x,y,z=placement["location_xyz_m"]
            pitch,yaw=placement["rotation_pitch_yaw_deg"]
            sensor=world.spawn_actor(blueprint,carla.Transform(
                carla.Location(x=x,y=y,z=z),carla.Rotation(pitch=pitch,yaw=yaw)))
            if sensor is None:raise ValueError(name+" Native camera spawn failed")
            sensors[name]=sensor
        return sensors
    except BaseException:
        for sensor in reversed(list(sensors.values())):sensor.destroy()
        raise

def sample_original_walker(scene,actor,snapshot):
    frame=int(snapshot.frame)
    time_s=float(snapshot.timestamp.elapsed_seconds)
    if frame<0 or not math.isfinite(time_s):raise ValueError("invalid original world frame")
    vertices=actor.bounding_box.get_world_vertices(actor.get_transform())
    if len(vertices)!=8:raise ValueError("original walker needs eight world-space vertices")
    xyz=[(float(v.x),float(v.y),float(v.z)) for v in vertices]
    if not all(math.isfinite(v) for p in xyz for v in p):
        raise ValueError("nonfinite original walker body")
    xs=[p[0] for p in xyz];ys=[p[1] for p in xyz]
    if max(xs)-min(xs)<.1 or max(ys)-min(ys)<.1:
        raise ValueError("degenerate original walker footprint")
    box=[[min(xs),min(ys)],[max(xs),min(ys)],[max(xs),max(ys)],[min(xs),max(ys)]]
    return {"case_id":scene["case_id"],"actor_id":int(actor.id),"frame":frame,
            "time_s":time_s,"body_xy_m":box,
            "body_center_xy_m":[(min(xs)+max(xs))/2,(min(ys)+max(ys))/2],
            "body_z_min_m":min(p[2] for p in xyz),"body_z_max_m":max(p[2] for p in xyz),
            "source":"original_native","source_kind":"original_native_world_vertices"}

class FourViewJoin:
    """Reject incomplete, stale or malformed camera frames before encoding."""

    def __init__(self):
        self.previous_frame = None
        self.previous_time_s = None

    def append(self, walker_sample, images):
        frame = walker_sample["frame"]
        time_s = walker_sample["time_s"]
        if self.previous_frame is not None:
            if frame != self.previous_frame+1:
                raise ValueError("original world frames are not consecutive")
            if abs(time_s-self.previous_time_s-.05) > .005:
                raise ValueError("original world frame timing is not 20 Hz")
        if set(images) != set(CAMERA_SPECS):
            raise ValueError("four named original camera views required")
        receipt = {"case_id": walker_sample["case_id"], "frame": frame,
                   "time_s": time_s, "walker_actor_id": walker_sample["actor_id"],
                   "cameras": {}}
        for name, (width, height) in CAMERA_SPECS.items():
            image = images[name]
            if (int(image.frame) != frame or int(image.width) != width or
                    int(image.height) != height or len(image.raw_data) != width*height*4):
                raise ValueError(name+" original camera frame, resolution or BGRA size differs")
            receipt["cameras"][name] = {"frame": frame, "width": width,
                                        "height": height, "pixel_format": "bgra",
                                        "bytes": width*height*4}
        self.previous_frame = frame
        self.previous_time_s = time_s
        return receipt


class FourVideoRecorder:
    """Acquire four synchronized original BGRA streams into lossless videos.

    A failed frame leaves the attempt incomplete. The caller must seal only after
    `close` succeeds and an independent decoder checks every resulting video.
    """

    def __init__(self, world, scene, carla, output, encoder_factory=None):
        self.output = Path(output)
        if not self.output.is_dir():
            raise ValueError("fresh existing Native attempt directory required")
        if any((self.output/(name+".mkv")).exists() for name in CAMERA_SPECS):
            raise ValueError("Native video outputs already exist")
        self.join = FourViewJoin()
        self.queues = {}
        self.sensors = {}
        self.encoders = {}
        self.errors = []
        self.closed = False
        encoder_factory = encoder_factory or subprocess.Popen
        try:
            self.sensors = spawn_native_cameras(world, scene, carla)
            for name, (width, height) in CAMERA_SPECS.items():
                inbox = queue.Queue(maxsize=4)
                self.queues[name] = inbox

                def receive(image, target=inbox, label=name):
                    try:
                        target.put_nowait(image)
                    except queue.Full:
                        self.errors.append("camera queue overflow: "+label)

                self.sensors[name].listen(receive)
                command = ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                           "-n", "-f", "rawvideo", "-pixel_format", "bgra",
                           "-video_size", f"{width}x{height}", "-framerate", "20",
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-pix_fmt", "bgra",
                           str(self.output/(name+".mkv"))]
                self.encoders[name] = encoder_factory(
                    command, stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)
        except BaseException:
            self.close()
            raise

    def append(self, walker_sample):
        if self.closed:
            raise ValueError("Native video recorder already closed")
        if self.errors:
            raise RuntimeError("; ".join(self.errors))
        images = {name: self.queues[name].get(timeout=15) for name in CAMERA_SPECS}
        receipt = self.join.append(walker_sample, images)
        for name, image in images.items():
            written = self.encoders[name].stdin.write(image.raw_data)
            if written != len(image.raw_data):
                raise RuntimeError(name+" encoder wrote incomplete original frame")
        return receipt

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in reversed(list(self.sensors.values())):
            try: sensor.stop()
            except BaseException as exc: errors.append("sensor stop: "+repr(exc))
        for name, encoder in self.encoders.items():
            try:
                if encoder.stdin and not encoder.stdin.closed:
                    encoder.stdin.close()
                if encoder.wait(timeout=180) != 0:
                    errors.append(name+" encoder failed")
            except BaseException as exc:
                errors.append(name+" encoder close: "+repr(exc))
        for sensor in reversed(list(self.sensors.values())):
            try: sensor.destroy()
            except BaseException as exc: errors.append("sensor destroy: "+repr(exc))
        if errors:
            raise RuntimeError("; ".join(errors))

"""Independent source checks for a saved pedestrian crossing attempt.

This intentionally cannot certify physical visibility or legal compliance.
"""
from __future__ import annotations

import math
from crossing_geometry import measure_original_history, point

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def audit_saved(scene, walker_rows, frame_joins, camera_sources, *, expected_camera_kind='original_native'):
    if set(camera_sources) != set(CAMERAS):
        raise ValueError('four exact camera sources required')
    for name, source in camera_sources.items():
        if not isinstance(source, dict) or source.get('kind') != expected_camera_kind or not source.get('sha256'):
            raise ValueError(f'{name}: original camera hash required')
    measured = measure_original_history(walker_rows, scene)
    frames = [row['frame'] for row in walker_rows]
    if frames != list(range(frames[0], frames[-1]+1)):
        raise ValueError('original walker frames must be contiguous')
    times = [row.get('time_s') for row in walker_rows]
    if any(type(t) not in (int, float) or not math.isfinite(t) for t in times):
        raise ValueError('original time missing or nonfinite')
    if any(abs((b-a)-0.05) > 0.001 for a, b in zip(times, times[1:])):
        raise ValueError('original frame cadence is not 20 Hz')
    if len(frame_joins) != len(walker_rows):
        raise ValueError('camera frame join length differs from walker history')
    for row, join in zip(walker_rows, frame_joins):
        if join.get('frame') != row['frame'] or abs(join.get('time_s', float('inf'))-row['time_s']) > 0.001:
            raise ValueError('camera and walker original frame join mismatch')
        if set(join.get('cameras', {})) != set(CAMERAS):
            raise ValueError('four camera frame joins required')
        for value in join['cameras'].values():
            if isinstance(value, dict):
                if value.get('frame') != row['frame']:
                    raise ValueError('invalid camera original frame')
            elif type(value) is not int or value < 0:
                raise ValueError('invalid camera frame index')
    measured['audit_kind'] = 'saved_source_structure'
    measured['physical_visibility'] = 'unconfirmed'
    return measured

"""Independent pair checks against exact controlled-difference declarations."""
from crossing_geometry import validate_scene


ALLOWED = {
    'right_angle_vs_neither': {'route_xy_m', 'construction_intent', 'case_id'},
    'shortest_vs_neither': {'route_xy_m', 'construction_intent', 'case_id'},
    'outside_vs_crosswalk_exception': {'crosswalk_boundaries_xy_m', 'crosswalk_context',
                                       'construction_intent', 'case_id', 'map_source_sha256'},
}


def audit_pair(comparison_id, left, right):
    validate_scene(left)
    validate_scene(right)
    if comparison_id not in ALLOWED:
        raise ValueError('unknown comparison')
    if left['case_id'] == right['case_id']:
        raise ValueError('comparison needs distinct cases')
    changed = {key for key in set(left) | set(right) if left.get(key) != right.get(key)}
    unreviewed = changed - ALLOWED[comparison_id]
    if unreviewed:
        raise ValueError('unreviewed comparison changes: ' + ', '.join(sorted(unreviewed)))
    required = ALLOWED[comparison_id] - {'construction_intent', 'case_id'}
    if not changed & required:
        raise ValueError('declared comparison variable did not change')
    return {'comparison_id': comparison_id, 'changed_fields': sorted(changed),
            'fixed_fields_checked': sorted(set(left) & set(right) - changed),
            'legal_judgment': 'unresolved', 'physical_realization': 'unconfirmed'}
